import numpy as np
from scipy.optimize import minimize

def objective(vars):
    p, q, r, s = vars
    return p/q + r/p + s/r + q/s

def constraint(vars):
    p, q, r, s = vars
    return (p + s) * (r + q) - (p * s + q * r)

cons = {'type': 'eq', 'fun': constraint}
bounds = [(0.001, 1000], (0.001, 1000), (0.001, 1000), (0.001, 1000)]

# Try several starting points and see if we always get 8
for i in range(5):
    x0 = np.random.rand(4) * 10 + 1
    res = minimize(objective, x0=x0, bounds=bounds, constraints=cons)
    print(f"Run {i}: E={res.fun}, x={res.x}")

